using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class SessionsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Sessions", "View"); return AdminDataService.GetList("Sessions"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Sessions", "View"); return AdminDataService.GetDefinitionMetadata("Sessions"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Sessions", "Delete"); return AdminDataService.Delete("Sessions", id); } } }
